import { buttonGroupVariants, type ButtonGroupVariants } from "./variants.ts";
import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"div">, ButtonGroupVariants {}

<const/{ orientation, class: className, content, ...rest }=input/>

<div
  role="group"
  data-slot="button-group"
  data-orientation=(orientation ?? "horizontal")
  ...rest
  class=cn(buttonGroupVariants({ orientation }), className)
>
  <${content}/>
</div>

import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"div"> {
  orientation?: "horizontal" | "vertical";
}

<const/{ orientation = "vertical", class: className, content, ...rest }=input/>

<div
  data-slot="button-group-separator"
  role="separator"
  data-orientation=orientation
  ...rest
  class=cn(
    "mu-button-group-separator relative self-stretch data-[orientation=horizontal]:mx-px data-[orientation=horizontal]:w-auto data-[orientation=vertical]:my-px data-[orientation=vertical]:h-auto",
    className,
  )
>
  <${content}/>
</div>

import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"div"> {}

<const/{ class: className, content, ...rest }=input/>

<div
  ...rest
  class=cn(
    "mu-button-group-text flex items-center [&_svg]:pointer-events-none",
    className,
  )
>
  <${content}/>
</div>

import { cva, type VariantProps } from "class-variance-authority";

export const buttonGroupVariants = cva(
  "mu-button-group group/button-group flex w-fit items-stretch *:focus-visible:relative *:focus-visible:z-10 [&>[data-slot=select-trigger]:not([class*='w-'])]:w-fit [&>input]:flex-1",
  {
    variants: {
      orientation: {
        horizontal:
          "mu-button-group-orientation-horizontal [&>*:not(:first-child)]:rounded-l-none [&>*:not(:first-child)]:border-l-0 [&>*:not(:last-child)]:rounded-r-none",
        vertical:
          "mu-button-group-orientation-vertical flex-col [&>*:not(:first-child)]:rounded-t-none [&>*:not(:first-child)]:border-t-0 [&>*:not(:last-child)]:rounded-b-none",
      },
    },
    defaultVariants: {
      orientation: "horizontal",
    },
  },
);

export type ButtonGroupVariants = VariantProps<typeof buttonGroupVariants>;
